-- GENERATED by gen_mxh3_vault.py -- models are generated, never hand-edited.
--   SAT_COVERAGE_SUBLIMIT_SCHEDULE
--   anchor      : HUB_COVERAGE
--   grain       : Multi-Active SCD2 (data_7.js sats[].hist)
--   child key   : Active Sequence Number
--   feeders     : 2 -- one per (view, DECLARED ANCHOR EXPRESSION)
--   payload     : 5 attribute(s), NULL-PADDED TO THE SATELLITE
--
--   The child key is the MODEL'S declared key, read from data_7.js
--   sats[].childkey keyed by sats[].code. target.key_name is the HUB key
--   name and is null on all 1,888 satellite rows, so it is never read here.
--
--   The hashdiff is GUARDED against an all-null input: without the guard
--   every all-null row hashes to ONE value and the population collapses.

with feeders as (select * from (
    select
        md5(upper(HUB_COVERAGE_BK__K0)) as HUB_COVERAGE_HK,
        'PROCEDURE_WISE' as ACTIVE_SEQUENCE_NUMBER,
        null::varchar as SUB_LIMIT_AMOUNT,
        PROCEDURE_LIMIT_FACTOR as SUB_LIMIT_PERCENTAGE,
        null::varchar as CAPPING_BASIS,
        ROOM_RENT_LIMIT_GROUP as ROOM_CATEGORY_LINKAGE,
        null::varchar as PER_DAY_LIMIT,
        'MAXI_HLTH_CLM_VW_DATA_CLAIM_DETAIL_CLAIMDETAIL_ATTRIBUTE_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_clm_cd_clmdetail_apv') }}
    where HUB_COVERAGE_K0__EMIT
    union all
    select
        md5(upper(HUB_COVERAGE_BK__K1)) as HUB_COVERAGE_HK,
        'BENEFIT_DAYS' as ACTIVE_SEQUENCE_NUMBER,
        SELF_PREHOSPITALIZATION_EXPENSES as SUB_LIMIT_AMOUNT,
        null::varchar as SUB_LIMIT_PERCENTAGE,
        ROOM_RENT_CAPPING as CAPPING_BASIS,
        null::varchar as ROOM_CATEGORY_LINKAGE,
        SELF_ROOM_RENT as PER_DAY_LIMIT,
        'MAXI_HLTH_UWR_VW_DATA_MEMBERS_MEMBER_DETAILS_PIVOT_VW' as RECORD_SOURCE,
        current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_uwr_mem_memd_pv') }}
    where HUB_COVERAGE_K1__EMIT
)), hashed as (select *,
        case when SUB_LIMIT_AMOUNT is not null or SUB_LIMIT_PERCENTAGE is not null or CAPPING_BASIS is not null or ROOM_CATEGORY_LINKAGE is not null or PER_DAY_LIMIT is not null
             then md5(upper(coalesce(SUB_LIMIT_AMOUNT::varchar,'') || '||' || coalesce(SUB_LIMIT_PERCENTAGE::varchar,'') || '||' || coalesce(CAPPING_BASIS::varchar,'') || '||' || coalesce(ROOM_CATEGORY_LINKAGE::varchar,'') || '||' || coalesce(PER_DAY_LIMIT::varchar,'')))
        end as SAT_COVERAGE_SUBLIMIT_SCHEDULE_HASHDIFF
    from feeders)

select * from hashed
where HUB_COVERAGE_HK is not null
  and SAT_COVERAGE_SUBLIMIT_SCHEDULE_HASHDIFF is not null
  and ACTIVE_SEQUENCE_NUMBER is not null
